```sql
SELECT "category", COUNT(DISTINCT "original_name") AS names, SUM((SELECT COUNT(*) FROM "layers_2026"."SocialServices_CL4_geom" s WHERE s."servicename_ar" = m."original_name")) AS total FROM "layers_2026"."service_name_mapping" m GROUP BY "category" ORDER BY total DESC;
