```sql
UPDATE "layers_2026"."service_name_mapping" SET "category" = CASE WHEN "original_name" LIKE '%لجنة%تنمية%' THEN 'لجنة تنمية اجتماعية' WHEN "original_name" LIKE '%مستودع%' THEN 'مستودع خيري' WHEN "original_name" LIKE '%جمعية%البر%' THEN 'جمعية خيرية' WHEN "original_name" LIKE '%تأهيل%' THEN 'مركز تأهيل' WHEN "original_name" LIKE '%مرفق%' THEN 'مرفق اجتماعي' WHEN "original_name" LIKE '%إغاثة%' OR "original_name" LIKE '%اغاثة%' THEN 'إغاثة' WHEN "original_name" LIKE '%ضمان%' THEN 'ضمان اجتماعي' ELSE "category" END WHERE "category" = 'أخرى';
